window.__sleep = ms => new Promise(r => setTimeout(r, ms));
window.__S = () => window.__ensemble.getState();
window.__ta = () => document.querySelector('.composer textarea');
window.__t = v => { const ta = window.__ta(); Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set.call(ta, v); ta.dispatchEvent(new Event('input', { bubbles: true })); ta.focus(); };
window.__enter = el => (el || window.__ta()).dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', bubbles: true, cancelable: true }));
window.__open = label => { const b = document.querySelector('.composer button[aria-label^="' + label + '"]'); if (!b) return false; b.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, button: 0, pointerType: 'mouse' })); return true };
window.__chat = () => { const s = window.__S(); return s.chats.find(c => c.id === s.chatId) };
window.__lead = () => { const s = window.__S(); const c = window.__chat(); return (c && c.leadId) || s.settings.leadId };
window.__k = () => window.__S().chatId + ':' + window.__lead();
window.__phase = () => (window.__S().agents[window.__k()] || {}).phase;
window.__busy = () => Object.values(window.__S().agents).filter(a => a.chatId === window.__S().chatId && a.phase !== 'idle' && a.phase !== 'error').length;
window.__txt = (n) => document.body.innerText.replace(/\s+/g, ' ').slice(0, n || 600);
window.__bt = re => [...document.querySelectorAll('button')].find(b => re.test(((b.textContent || '').trim()) || b.getAttribute('aria-label') || ''));
window.__bl = re => [...document.querySelectorAll('button')].find(b => re.test(b.getAttribute('aria-label') || ''));
window.__bottom = () => { const sc = document.querySelector('[data-view-scope]')?.parentElement; if (sc) sc.scrollTop = sc.scrollHeight; };
window.__new = async () => { window.__S().setView('chat'); window.__S().newChat(); await window.__sleep(700); };
window.__waitIdle = async (max) => { const t0 = Date.now(); while (Date.now() - t0 < (max || 40000)) { await window.__sleep(500); if (window.__busy() === 0) return Math.round((Date.now() - t0) / 1000) + 's'; } return 'still busy after ' + (max || 40000) + 'ms'; };
window.__items = () => (window.__S().items[window.__k()] || []).map(i => i.kind + (i.event ? ':' + i.event : '') + (i.queued ? '(queued)' : '')).join(',');
window.__toasts = () => window.__S().toasts.map(t => t.text).join(' | ');

for (let i = 0; i < 10; i++) {
  if (window.__S().settings.onboarded) break;
  const all = [...document.querySelectorAll('button')].filter(b => !b.disabled);
  const find = re => all.find(b => re.test(b.textContent.trim()));
  const b = find(/^(Continue|Start using|Start with|Get started|Start working|Done|Finish|Open Ensemble)/) || find(/^Skip/);
  if (!b) break; b.click(); await window.__sleep(900);
}
return 'onboarded=' + window.__S().settings.onboarded + ' accounts=' + window.__S().accounts.map(a => a.name + (a.enabled ? '' : '(off)')).join(',');

const out = [];
for (const d of [800, 1500, 2000, 2500, 3200, 4500]) {
  await window.__new();
  await window.__S().send('Add a pricing page with a checkout flow');
  await window.__sleep(d);
  const s = window.__S(); const lead = window.__lead(); const k = s.chatId + ':' + lead;
  const before = (s.agents[k]||{}).phase + '/' + window.__busy();
  await window.ensemble.stop(s.chatId, lead);
  await window.__sleep(1500);
  const mid = (window.__S().agents[k]||{}).phase + '/' + window.__busy();
  await window.__sleep(3000);
  const after = (window.__S().agents[k]||{}).phase + '/' + window.__busy();
  out.push('stop(lead) at ' + d + 'ms: ' + before + ' -> +1.5s ' + mid + ' -> +4.5s ' + after);
  await window.ensemble.stop(s.chatId); await window.__sleep(800);
}
return out.join(' || ');

const out = [];
for (const d of [1500, 2000, 2500, 3200]) {
  await window.__new();
  await window.__S().send('Add a pricing page with a checkout flow');
  await window.__sleep(d);
  const before = window.__busy();
  document.activeElement && document.activeElement.blur();
  const ev = new KeyboardEvent('keydown', { key: 'Escape', code: 'Escape', bubbles: true, cancelable: true }); document.body.dispatchEvent(ev);
  await window.__sleep(1500);
  const mid = window.__busy() + ' ' + (window.__S().agents[window.__k()]||{}).phase;
  await window.__sleep(3000);
  out.push('Esc at ' + d + 'ms: busy ' + before + ' handled=' + ev.defaultPrevented + ' -> +1.5s ' + mid + ' -> +4.5s ' + window.__busy());
  await window.ensemble.stop(window.__S().chatId); await window.__sleep(800);
}
return out.join(' || ');
